// Normalize and validate input
const input = $input.first().json;

const title = input.title;
const content = input.content;
const slug = input.slug || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const excerpt = input.excerpt || content.substring(0, 200).replace(/[#*\n]/g, ' ').trim() + '...';
const tags = input.tags || ['stashdog'];
const metaDescription = input.meta_description || excerpt.substring(0, 155);
const authorId = input.author_id || '1dd2a897-03ac-4a5f-b374-d8894d4394d2';
const generateImage = input.generate_image !== false; // default true
const imageStyle = input.image_style || 'default'; // 'default' uses StashDog brand SVG

if (!title || !content) {
  throw new Error('Missing required fields: title and content are required');
}

return [{
  json: {
    title,
    content,
    slug,
    excerpt,
    tags: Array.isArray(tags) ? tags : tags.split(',').map(t => t.trim()),
    metaDescription,
    authorId,
    generateImage,
    imageStyle
  }
}];

