// Extract SVG from LLM response
const response = $input.first().json;
const llmContent = response.choices?.[0]?.message?.content || '';

// Extract SVG — strip markdown fences if present
let svg = llmContent;
if (svg.includes('<svg')) {
  svg = svg.substring(svg.indexOf('<svg'));
  const endIdx = svg.lastIndexOf('</svg>');
  if (endIdx !== -1) {
    svg = svg.substring(0, endIdx + 6);
  }
}

// Get the normalized data from earlier in the chain
const blogData = $('Normalize Input').first().json;
const fileName = `blog-${blogData.slug}-hero.svg`;

return [{
  json: {
    ...blogData,
    svgContent: svg,
    fileName
  }
}];

// Build the public image URL and prepare for DB insert
const data = $input.first().json;
const imageUrl = `https://gmchczeyburroiyzefie.supabase.co/storage/v1/object/public/blog-assets/${data.fileName}`;

return [{
  json: {
    ...data,
    featuredImageUrl: imageUrl
  }
}];

// Skip image gen — just pass through with no image
const blogData = $('Normalize Input').first().json;

return [{
  json: {
    ...blogData,
    featuredImageUrl: null,
    fileName: null
  }
}];

// Update marketing_content pipeline status if matching title exists
const blogPost = $input.first().json;
const blogData = $('Normalize Input').first().json;

const postId = Array.isArray(blogPost) ? blogPost[0]?.id : blogPost?.id;
const slug = blogData.slug;

return [{
  json: {
    postId,
    slug,
    title: blogData.title,
    url: `https://stashdog.io/blog/${slug}/`
  }
}];

